export default function HomePage() {
  return <h1>Northstar Publishing</h1>
}
export const revalidate = 3600

async function getStories() {
  await new Promise((resolve) => setTimeout(resolve, 80))
  return ['City council approves new park', 'Night market opens Friday']
}

export default async function NewsPage() {
  const stories = await getStories()

  return (
    <main>
      <h1>Newsroom</h1>
      {stories.map((story) => (
        <article key={story}>{story}</article>
      ))}
    </main>
  )
}
import { cookies } from 'next/headers'

export const dynamic = 'force-dynamic'

export default async function PreviewPage() {
  const draft = (await cookies()).get('draft-title')?.value ?? 'Untitled draft'

  return (
    <main>
      <h1>Editor preview</h1>
      <p>{draft}</p>
    </main>
  )
}
import Link from 'next/link'
import type { ReactNode } from 'react'

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body>
        <nav>
          <Link href="/news">Newsroom</Link>{' '}
          <Link href="/preview">Editor preview</Link>
        </nav>
        {children}
      </body>
    </html>
  )
}

